package com.spiralworld.spiraldine

import com.spiralworld.spiraldine.data.repository.QrParser
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

class QrParserTest {

    // 1. Website Canonical URL formats generated by OwnerTablesManager.tsx:
    //    ${window.location.origin}/r/${tenantId}/table/${tableId}
    @Test
    fun parseWebsiteTableUrl_numericTable_returnsCorrectTenantAndTable() {
        val url = "https://spiral-dine.vercel.app/r/res-821720/table/1"
        val result = QrParser.parse(url)

        assertNotNull("Should recognize website canonical table URL", result)
        assertEquals("res-821720", result?.tenantId)
        assertEquals("1", result?.tableNumber)
    }

    @Test
    fun parseWebsiteTableUrl_prefixedTableId_stripsPrefix() {
        val url = "https://spiral-dine.vercel.app/r/yummy-yummy-3p65/table/TBL-12"
        val result = QrParser.parse(url)

        assertNotNull(result)
        assertEquals("yummy-yummy-3p65", result?.tenantId)
        assertEquals("12", result?.tableNumber)
    }

    @Test
    fun parseWebsiteRestaurantMenuUrl_withoutTable_defaultsToOne() {
        val url = "https://spiral-dine.vercel.app/r/res-821720"
        val result = QrParser.parse(url)

        assertNotNull(result)
        assertEquals("res-821720", result?.tenantId)
        assertEquals("1", result?.tableNumber)
    }

    @Test
    fun parseWebsiteRestaurantMenuUrl_withTableQueryParam() {
        val url = "https://spiral-dine.vercel.app/r/res-821720?table=7"
        val result = QrParser.parse(url)

        assertNotNull(result)
        assertEquals("res-821720", result?.tenantId)
        assertEquals("7", result?.tableNumber)
    }

    @Test
    fun parseWebsiteRelativePath_isSupported() {
        val relative = "/r/res-821720/table/5"
        val result = QrParser.parse(relative)

        assertNotNull(result)
        assertEquals("res-821720", result?.tenantId)
        assertEquals("5", result?.tableNumber)
    }

    // 2. JSON Payloads (often generated by direct QR builders or POS bridges)
    @Test
    fun parseJsonPayload_withTableNumber() {
        val json = """{"tenantId":"res-821720","tableNumber":"3"}"""
        val result = QrParser.parse(json)

        assertNotNull(result)
        assertEquals("res-821720", result?.tenantId)
        assertEquals("3", result?.tableNumber)
    }

    @Test
    fun parseJsonPayload_withTableIdAndRestaurantId() {
        val json = """{"restaurantId":"yummy-yummy-3p65","tableId":"TBL-8"}"""
        val result = QrParser.parse(json)

        assertNotNull(result)
        assertEquals("yummy-yummy-3p65", result?.tenantId)
        assertEquals("8", result?.tableNumber)
    }

    // 3. Supported Legacy Formats
    @Test
    fun parseStandardWebCustomerUrl_legacyMenuRoute() {
        val url = "https://spiral-dine.vercel.app/customer/restaurant/tenant-spicy-bites/menu?table=14"
        val result = QrParser.parse(url)

        assertNotNull(result)
        assertEquals("tenant-spicy-bites", result?.tenantId)
        assertEquals("14", result?.tableNumber)
    }

    @Test
    fun parseShortQrUrl_returnsCorrectTenantAndTable() {
        val url = "https://spiral-dine.vercel.app/qr/rest-oasis/7"
        val result = QrParser.parse(url)

        assertNotNull(result)
        assertEquals("rest-oasis", result?.tenantId)
        assertEquals("7", result?.tableNumber)
    }

    @Test
    fun parseCustomScheme_returnsCorrectTenantAndTable() {
        val uri = "spiraldine://table?tenant=kitchen-hub-42&table=9"
        val result = QrParser.parse(uri)

        assertNotNull(result)
        assertEquals("kitchen-hub-42", result?.tenantId)
        assertEquals("9", result?.tableNumber)
    }

    @Test
    fun parseCompactFormat_returnsCorrectTenantAndTable() {
        val compact = "biryani-junction:3"
        val result = QrParser.parse(compact)

        assertNotNull(result)
        assertEquals("biryani-junction", result?.tenantId)
        assertEquals("3", result?.tableNumber)
    }

    // 4. Malformed, External Phishing, and Missing Identifier Tests
    @Test
    fun parsePhishingOrExternalUrl_isRejected() {
        val evilUrl = "https://malicious-phishing-site.com/fake-menu?tenant=hacked&table=1"
        val result = QrParser.parse(evilUrl)

        assertNull("External untrusted host must be rejected for customer security", result)
    }

    @Test
    fun parseEmptyOrMalformed_returnsNull() {
        assertNull(QrParser.parse(null))
        assertNull(QrParser.parse(""))
        assertNull(QrParser.parse("   "))
        assertNull(QrParser.parse("not a valid code at all"))
    }

    @Test
    fun parseMissingTenantId_returnsNull() {
        val url = "https://spiral-dine.vercel.app/r//table/2"
        val result = QrParser.parse(url)
        assertNull(result)
    }

    // 5. Repeated Scan Prevention Logic
    @Test
    fun repeatedScanThrottling_preventsDuplicateTrigger() {
        var lastScannedPayload: String? = null
        var lastScannedTime = 0L
        val throttleWindowMs = 2500L

        fun canProcessScan(payload: String, currentTime: Long): Boolean {
            if (payload == lastScannedPayload && (currentTime - lastScannedTime) < throttleWindowMs) {
                return false
            }
            lastScannedPayload = payload
            lastScannedTime = currentTime
            return true
        }

        val testPayload = "https://spiral-dine.vercel.app/r/res-821720/table/1"
        val t0 = 10000L

        // First scan succeeds
        assertTrue("First scan must be processed", canProcessScan(testPayload, t0))

        // Immediate subsequent scan within window is throttled
        assertFalse("Duplicate scan at +500ms must be throttled", canProcessScan(testPayload, t0 + 500))
        assertFalse("Duplicate scan at +2000ms must be throttled", canProcessScan(testPayload, t0 + 2000))

        // Different payload passes even within window
        val otherPayload = "https://spiral-dine.vercel.app/r/res-821720/table/2"
        assertTrue("Different table QR must be processed immediately", canProcessScan(otherPayload, t0 + 2100))

        // Same original payload after throttle window passes
        assertTrue("Same QR after throttle window expired must be processed", canProcessScan(otherPayload, t0 + 2100 + 3000))
    }
}
